link.script:
(() => {
  const currentUrl = new URL(window.location.href);
  if (currentUrl.searchParams.get('ii_item_modal') !== '1') return;

  const originParam = currentUrl.searchParams.get('ii_modal_origin');
  if (!originParam) return;

  let originUrl;
  try {
    originUrl = new URL(originParam, window.location.origin);
  } catch (error) {
    return;
  }

  if (originUrl.origin !== window.location.origin) return;

  const cleanCurrentUrl = new URL(currentUrl.toString());
  cleanCurrentUrl.searchParams.delete('ii_item_modal');
  cleanCurrentUrl.searchParams.delete('ii_modal_origin');
  cleanCurrentUrl.searchParams.delete('modal_embed');
  cleanCurrentUrl.searchParams.delete('ii_open_item_modal');

  const cleanOriginUrl = new URL(originUrl.toString());
  cleanOriginUrl.searchParams.delete('ii_open_item_modal');

  const currentSignature = `${cleanCurrentUrl.pathname}${cleanCurrentUrl.search}${cleanCurrentUrl.hash || ''}`;
  const originSignature = `${cleanOriginUrl.pathname}${cleanOriginUrl.search}${cleanOriginUrl.hash || ''}`;
  if (originSignature === currentSignature) return;

  cleanOriginUrl.searchParams.set('ii_open_item_modal', cleanCurrentUrl.toString());
  window.location.replace(cleanOriginUrl.toString());
})();

window.__iiAds = Object.assign({}, window.__iiAds || {}, {
  provider: "snigel",
  mode: "snigel",
  flexbarEnabled: false,
});

document.addEventListener('alpine:init', () => {
  // lee preferencia guardada; por defecto abierto en desktop y cerrado en móvil
  const saved = localStorage.getItem('filters.visible');
  const isDesktop = window.matchMedia('(min-width:1024px)').matches;
  Alpine.store('filters', {
    visible: saved === null ? isDesktop : (saved === 'true')
  });
});

window.IconIconsContextUrl = {
  build(options = {}) {
    const reopenUpgradeModal = options.reopenUpgradeModal === true;
    const extraParams = options.extraParams && typeof options.extraParams === 'object'
      ? options.extraParams
      : {};
    const currentUrl = new URL(window.location.href);

    const serializeRelative = (url) => `${url.pathname}${url.search}${url.hash}`;

    const applyExtraParams = (url) => {
      Object.entries(extraParams).forEach(([key, value]) => {
        if (value === null || value === undefined || value === '') {
          url.searchParams.delete(key);
          return;
        }
        url.searchParams.set(key, String(value));
      });

      return url;
    };

    const applyUpgradeIntent = (url) => {
      url.searchParams.delete('ii_open_upgrade_modal');
      if (reopenUpgradeModal) {
        url.searchParams.set('ii_open_upgrade_modal', '1');
      }
      return applyExtraParams(url);
    };

    if (currentUrl.searchParams.get('ii_item_modal') === '1') {
      const originParam = currentUrl.searchParams.get('ii_modal_origin');
      if (originParam) {
        try {
          const originUrl = new URL(originParam, window.location.origin);
          if (originUrl.origin === window.location.origin) {
            const cleanCurrentUrl = new URL(currentUrl.toString());
            cleanCurrentUrl.searchParams.delete('ii_item_modal');
            cleanCurrentUrl.searchParams.delete('ii_modal_origin');
            cleanCurrentUrl.searchParams.delete('ii_open_item_modal');
            cleanCurrentUrl.searchParams.delete('ii_open_upgrade_modal');
            applyExtraParams(cleanCurrentUrl);

            const cleanOriginUrl = new URL(originUrl.toString());
            cleanOriginUrl.searchParams.delete('ii_open_item_modal');
            applyUpgradeIntent(cleanOriginUrl);
            cleanOriginUrl.searchParams.set('ii_open_item_modal', cleanCurrentUrl.toString());

            return serializeRelative(cleanOriginUrl);
          }
        } catch (_) {
        }
      }
    }

    return serializeRelative(applyUpgradeIntent(new URL(currentUrl.toString())));
  }
};

