div.script:
(function () {
  window.showTopMessage = function (message, type = 'success', ms = 2000, action = null) {
    const box = document.getElementById('top-message');
    const text = document.getElementById('top-message-text');
    const actionBtn = document.getElementById('top-message-action');
    if (!box || !text || !actionBtn) return false;

    const unifiedTone = ['bg-slate-800', 'text-white'];
    const toneMap = {
      success: unifiedTone,
      info: unifiedTone,
      warning: unifiedTone,
      error: unifiedTone,
    };
    const allToneClasses = [
      'bg-slate-800', 'text-white',
      'bg-white', 'text-slate-800',
      'bg-amber-50', 'text-amber-900',
      'bg-rose-50', 'text-rose-900',
    ];
    const safeType = Object.prototype.hasOwnProperty.call(toneMap, type) ? type : 'success';
    box.classList.remove(...allToneClasses);
    box.classList.add(...toneMap[safeType]);

    text.textContent = String(message || '');
    if (action && typeof action === 'object' && action.url && action.label) {
      actionBtn.textContent = String(action.label);
      actionBtn.href = String(action.url);
      actionBtn.classList.remove('hidden');
    } else {
      actionBtn.textContent = '';
      actionBtn.href = '#';
      actionBtn.classList.add('hidden');
    }

    box.classList.remove('hidden', 'opacity-0');
    box.classList.add('opacity-100');

    clearTimeout(box._tmr);
    const delay = Math.max(1000, Number(ms) || 0);
    box._tmr = setTimeout(() => {
      box.classList.remove('opacity-100');
      box.classList.add('opacity-0');
      setTimeout(() => box.classList.add('hidden'), 220);
    }, delay);
    return true;
  };

        })();

(function () {
  const cartLabel = "Go to cart";
  const addedFallback = "Icon added to cart.";
  const errorFallback = "Invalid product.";
  const unexpectedFallback = "These credentials do not match our records.";
  const isJson = (response) => {
    const contentType = String(response.headers.get('content-type') || '');
    return contentType.includes('application/json');
  };

  const updateCartBadges = (count) => {
    const safeCount = Number(count) || 0;
    document.querySelectorAll('[data-cart-count-badge]').forEach((badge) => {
      if (!(badge instanceof HTMLElement)) return;
      badge.textContent = String(safeCount);
      badge.classList.toggle('hidden', safeCount <= 0);
    });
  };
  window.updateCartBadges = updateCartBadges;

  const submitCartFormAsync = async (form) => {
    const formData = new FormData(form);
    const response = await fetch(form.action, {
      method: 'POST',
      body: formData,
      credentials: 'same-origin',
      headers: {
        'X-Requested-With': 'XMLHttpRequest',
        'Accept': 'application/json',
      },
    });

    if (!isJson(response)) {
      window.location.href = response.url || form.action;
      return;
    }

    const data = await response.json();
    if (response.ok && data && data.ok) {
      updateCartBadges(data.cart_count);
      window.showTopMessage(
        data.message || addedFallback,
        data.type || 'success',
        4500,
        data.cart_url ? { label: cartLabel, url: data.cart_url } : null
      );
      return;
    }

    window.showTopMessage(
      (data && data.message) ? data.message : errorFallback,
      (data && data.type) ? data.type : 'error',
      3000
    );
  };

  document.addEventListener('submit', (event) => {
    const form = event.target;
    if (!(form instanceof HTMLFormElement)) return;
    if (!form.matches('form[data-cart-add-form="1"]')) return;

    event.preventDefault();
    if (form.dataset.submitting === '1') return;
    form.dataset.submitting = '1';

    submitCartFormAsync(form)
      .catch(() => {
        window.showTopMessage(unexpectedFallback, 'error', 2600);
      })
      .finally(() => {
        form.dataset.submitting = '0';
      });
  });
})();

(() => {
  if (window.__iiStorefrontPricingPreviewBooted) {
    return;
  }
  window.__iiStorefrontPricingPreviewBooted = true;

  const defaultPreviewUrl = "https:\/\/icon-icons.com\/storefront\/pricing-preview";
  const responseCache = new Map();

  function collectRoots(container) {
    if (!container) {
      return [];
    }

    const roots = [];
    if (container instanceof Element && container.matches('[data-storefront-pricing-root="1"]')) {
      roots.push(container);
    }

    if (typeof container.querySelectorAll === 'function') {
      container.querySelectorAll('[data-storefront-pricing-root="1"]').forEach((node) => {
        roots.push(node);
      });
    }

    return roots;
  }

  function buildPreviewUrl(root) {
    const previewUrl = root.getAttribute('data-storefront-pricing-preview-url') || defaultPreviewUrl;
    if (!previewUrl) {
      return null;
    }

    const url = new URL(previewUrl, window.location.origin);
    const linePriceCents = root.getAttribute('data-storefront-line-price-cents');
    const packPriceCents = root.getAttribute('data-storefront-pack-price-cents');
    const includeSubscription = root.getAttribute('data-storefront-include-subscription');

    if (linePriceCents !== null && linePriceCents !== '') {
      url.searchParams.set('line_price_cents', linePriceCents);
    }

    if (packPriceCents !== null && packPriceCents !== '') {
      url.searchParams.set('pack_price_cents', packPriceCents);
    }

    if (includeSubscription === '1') {
      url.searchParams.set('include_subscription', '1');
    }

    return url.searchParams.toString() === '' ? null : url.toString();
  }

  function fetchPreview(previewUrl) {
    if (!responseCache.has(previewUrl)) {
      responseCache.set(previewUrl, fetch(previewUrl, {
        credentials: 'same-origin',
        headers: {
          'Accept': 'application/json',
          'X-Requested-With': 'XMLHttpRequest',
        },
      }).then((response) => {
        if (!response.ok) {
          throw new Error(`Storefront pricing preview failed: ${response.status}`);
        }

        return response.json();
      }));
    }

    return responseCache.get(previewUrl);
  }

  function applyPreview(root, payload) {
    const linePriceLabel = payload?.line_price?.label;
    const packPriceLabel = payload?.pack_price?.label;
    const proFromPriceLabel = payload?.subscription_pricing?.annual_per_month_with_suffix_label;

    if (payload && typeof payload === 'object') {
      window.__iiStorefrontPricingContext = {
        countryCode: payload.country_code || null,
        storefrontCurrency: payload.storefront_currency || null,
        formatLocale: payload.format_locale || null,
        subscriptionPricing: payload.subscription_pricing || null,
      };
    }

    if (typeof linePriceLabel === 'string' && linePriceLabel !== '') {
      root.querySelectorAll('[data-storefront-line-price-label]').forEach((node) => {
        node.textContent = linePriceLabel;
      });
    }

    if (typeof packPriceLabel === 'string' && packPriceLabel !== '') {
      root.querySelectorAll('[data-storefront-pack-price-label]').forEach((node) => {
        node.textContent = packPriceLabel;
      });
    }

    if (typeof proFromPriceLabel === 'string' && proFromPriceLabel !== '') {
      root.querySelectorAll('[data-storefront-pro-from-price-label]').forEach((node) => {
        node.textContent = proFromPriceLabel;
      });
    }
  }

  function hydrateRoot(root) {
    if (!(root instanceof Element) || root.dataset.storefrontPricingHydrated === '1') {
      return;
    }

    const previewUrl = buildPreviewUrl(root);
    if (!previewUrl) {
      root.dataset.storefrontPricingHydrated = '1';
      root.dataset.storefrontPricingPending = '0';
      root.setAttribute('aria-busy', 'false');
      return;
    }

    root.dataset.storefrontPricingHydrated = '1';
    root.dataset.storefrontPricingPending = '1';
    root.setAttribute('aria-busy', 'true');

    fetchPreview(previewUrl)
      .then((payload) => {
        applyPreview(root, payload);
        root.dataset.storefrontPricingPending = '0';
        root.setAttribute('aria-busy', 'false');
      })
      .catch(() => {
        root.dataset.storefrontPricingHydrated = 'error';
        root.dataset.storefrontPricingPending = '0';
        root.setAttribute('aria-busy', 'false');
      });
  }

  function refresh(container = document) {
    collectRoots(container).forEach(hydrateRoot);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => refresh(document), { once: true });
  } else {
    refresh(document);
  }

  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        if (node instanceof Element) {
          refresh(node);
        }
      });
    });
  });

  observer.observe(document.documentElement, { childList: true, subtree: true });
  window.iiRefreshStorefrontPricing = refresh;
})();

if (!window.__iconIconsAuthGoogleBooted) {
  window.__iconIconsAuthGoogleBooted = true;

  document.addEventListener('DOMContentLoaded', function () {
    const clientId = "872913439091-80bvg159455rbe4vpu19pb69rfqodit1.apps.googleusercontent.com";
    const tokenUrl = "https:\/\/icon-icons.com\/auth\/google\/token";

    const getOpenModal = () => {
      return Array.from(document.querySelectorAll('[data-auth-modal-root="1"]')).find((modal) => modal.style.display === 'flex') || null;
    };

    const hideGoogleErrors = (root = document) => {
      root.querySelectorAll('[data-auth-google-error-general]').forEach((node) => {
        node.textContent = '';
        node.classList.add('hidden');
      });
    };

    const showGoogleError = (message) => {
      const modal = getOpenModal();
      const panel = modal?.querySelector('[data-auth-tab-panel="login"]:not(.hidden), [data-auth-tab-panel="register"]:not(.hidden)');
      const errorNode = panel?.querySelector('[data-auth-google-error-general]');
      if (!errorNode) {
        return;
      }

      errorNode.textContent = message;
      errorNode.classList.remove('hidden');
    };

    const resolveNext = () => {
      const contextNext = window.__iconIconsGoogleAuthContext?.next;
      if (contextNext) {
        return String(contextNext);
      }

      const modal = getOpenModal();
      const nextInput = modal?.querySelector('input[name="next"]');
      if (nextInput?.value) {
        return String(nextInput.value);
      }

      return window.location.pathname + window.location.search;
    };

    const postCredential = async (credential) => {
      hideGoogleErrors();

      try {
        const response = await fetch(tokenUrl, {
          method: 'POST',
          credentials: 'same-origin',
          headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '',
          },
          body: JSON.stringify({
            credential,
            next: resolveNext(),
          }),
        });

        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
          throw new Error(payload.message || 'Could not sign in with Google.');
        }

        window.location.assign(String(payload.redirect || resolveNext()));
      } catch (error) {
        showGoogleError(error?.message || 'Could not sign in with Google.');
      }
    };

    const renderButtons = (root = document, force = false) => {
      if (!window.google?.accounts?.id) {
        return;
      }

      root.querySelectorAll('[data-auth-google-button="1"]').forEach((container) => {
        if (!force && container.dataset.rendered === '1') {
          return;
        }

        const wrapper = container.closest('[data-auth-google-button-wrapper="1"]');
        const fallback = wrapper?.querySelector('[data-auth-google-fallback]');
        const wrapperWidth = Math.floor(wrapper?.getBoundingClientRect?.().width || wrapper?.clientWidth || 0);
        const width = Math.max(220, wrapperWidth > 0 ? wrapperWidth : 320);

        if (fallback) {
          fallback.classList.add('hidden');
        }

        container.innerHTML = '';
        container.classList.remove('hidden');
        container.dataset.rendered = '0';

        window.google.accounts.id.renderButton(container, {
          theme: 'outline',
          size: 'large',
          shape: 'pill',
          text: 'signin_with',
          logo_alignment: 'right',
          width,
        });

        container.dataset.rendered = '1';
      });
    };

    const initializeGoogleAuth = () => {
      if (!clientId || !window.google?.accounts?.id) {
        return;
      }

      window.google.accounts.id.initialize({
        client_id: clientId,
        use_fedcm_for_button: true,
        button_auto_select: true,
        callback: (response) => {
          if (!response?.credential) {
            showGoogleError('Could not sign in with Google.');
            return;
          }

          postCredential(response.credential);
        },
      });

      renderButtons();
      window.IconIconsAuthGoogle = {
        renderButtons,
        setContext(next) {
          window.__iconIconsGoogleAuthContext = { next };
        },
      };
    };

    if (window.google?.accounts?.id) {
      initializeGoogleAuth();
      return;
    }

    const existing = document.querySelector('script[data-google-identity="1"]');
    if (existing) {
      existing.addEventListener('load', initializeGoogleAuth, { once: true });
      return;
    }

    const script = document.createElement('script');
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true;
    script.defer = true;
    script.dataset.googleIdentity = '1';
    script.addEventListener('load', initializeGoogleAuth, { once: true });
    document.head.appendChild(script);
  });
}

document.addEventListener('DOMContentLoaded', function () {
  document.querySelectorAll('[data-password-toggle-root]').forEach(function (root) {
    if (!(root instanceof HTMLElement) || root.dataset.passwordToggleBooted === '1') {
      return;
    }

    const input = root.querySelector('[data-password-toggle-input]');
    const button = root.querySelector('[data-password-toggle-button]');
    const showIcon = root.querySelector('[data-password-icon="show"]');
    const hideIcon = root.querySelector('[data-password-icon="hide"]');
    const showLabel = root.getAttribute('data-password-show-label') || 'Show password';
    const hideLabel = root.getAttribute('data-password-hide-label') || 'Hide password';

    if (!(input instanceof HTMLInputElement) || !(button instanceof HTMLButtonElement)) {
      return;
    }

    const syncState = function () {
      const isVisible = input.type === 'text';
      button.setAttribute('aria-pressed', isVisible ? 'true' : 'false');
      button.setAttribute('aria-label', isVisible ? hideLabel : showLabel);
      button.setAttribute('title', isVisible ? hideLabel : showLabel);
      if (showIcon) showIcon.classList.toggle('hidden', isVisible);
      if (hideIcon) hideIcon.classList.toggle('hidden', !isVisible);
    };

    button.addEventListener('click', function () {
      input.type = input.type === 'password' ? 'text' : 'password';
      syncState();
    });

    syncState();
    root.dataset.passwordToggleBooted = '1';
  });
});

document.addEventListener('DOMContentLoaded', function () {
  const modal = document.getElementById('site-auth-modal');
  if (!modal) return;
  if (modal.dataset.booted === '1') return;
  modal.dataset.booted = '1';

  const loginForm = modal.querySelector('[data-auth-login-form="1"]');
  const registerForm = modal.querySelector('[data-auth-register-form="1"]');
  const generalError = modal.querySelector('[data-auth-login-error-general]');
  const registerGeneralError = modal.querySelector('[data-auth-register-error-general]');
  const loginUrl = "https:\/\/icon-icons.com\/login";
  const registerUrl = "https:\/\/icon-icons.com\/register";
  const registerTabButton = modal.querySelector('[data-auth-tab-trigger="register"]');
  const loginTabButton = modal.querySelector('[data-auth-tab-trigger="login"]');
  const loginPanel = modal.querySelector('[data-auth-tab-panel="login"]');
  const registerPanel = modal.querySelector('[data-auth-tab-panel="register"]');
  const registerSubmitButton = registerForm?.querySelector('button[type="submit"]');
  const registerRecaptchaContainer = registerForm?.querySelector('[data-auth-register-recaptcha]');
  const registerRecaptchaEnabled = true;
  const registerRecaptchaSiteKey = "6LcoKUQUAAAAAFt4nqCN6D6R30VZSidocyQFSDn-";
  const registerRecaptchaErrorMessage = "validation.recaptcha";
  let registerRecaptchaWidgetId = null;
  let registerPendingSubmission = null;
  const defaultNext = "\/icon\/youtube-logo\/102568";
  const buildContextNext = (reopenUpgradeModal = false) => {
    if (window.IconIconsContextUrl?.build) {
      return window.IconIconsContextUrl.build({ reopenUpgradeModal });
    }
    const fallback = new URL(window.location.href);
    fallback.searchParams.delete('ii_open_upgrade_modal');
    if (reopenUpgradeModal) {
      fallback.searchParams.set('ii_open_upgrade_modal', '1');
    }
    return `${fallback.pathname}${fallback.search}${fallback.hash}`;
  };

  const resolveTriggerNext = (trigger) => {
    if (!(trigger instanceof HTMLElement)) return defaultNext;
    const useCurrent = trigger.getAttribute('data-auth-next-current') === '1';
    const reopenUpgradeModal = trigger.getAttribute('data-auth-open-upgrade-after') === '1';

    if (useCurrent) {
      return buildContextNext(reopenUpgradeModal);
    }

    const rawNext = trigger.getAttribute('data-auth-next') || defaultNext;
    if (!reopenUpgradeModal) {
      return rawNext;
    }

    try {
      const nextUrl = new URL(rawNext, window.location.origin);
      if (nextUrl.origin === window.location.origin) {
        nextUrl.searchParams.set('ii_open_upgrade_modal', '1');
        return `${nextUrl.pathname}${nextUrl.search}${nextUrl.hash}`;
      }
    } catch (_) {
    }

    return buildContextNext(true);
  };

  const closeModal = () => {
    modal.style.display = 'none';
    modal.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('overflow-hidden');
  };

  const setTab = (tab) => {
    const isRegister = tab === 'register';
    if (loginTabButton) loginTabButton.dataset.active = isRegister ? 'false' : 'true';
    if (registerTabButton) registerTabButton.dataset.active = isRegister ? 'true' : 'false';
    if (loginPanel) loginPanel.classList.toggle('hidden', isRegister);
    if (registerPanel) registerPanel.classList.toggle('hidden', !isRegister);

    const activePanel = isRegister ? registerPanel : loginPanel;
    if (activePanel) {
      window.requestAnimationFrame(() => {
        window.IconIconsAuthGoogle?.renderButtons(activePanel, true);
      });
    }
  };

  const openModal = (tab, next) => {
    const loginNextInput = loginForm?.querySelector('input[name="next"]');
    const registerNextInput = registerForm?.querySelector('input[name="next"]');
    if (loginNextInput && next) loginNextInput.value = next;
    if (registerNextInput && next) registerNextInput.value = next;
    setTab(tab === 'register' ? 'register' : 'login');
    modal.style.display = 'flex';
    modal.setAttribute('aria-hidden', 'false');
    document.body.classList.add('overflow-hidden');
    window.IconIconsAuthGoogle?.setContext(next);
    window.IconIconsAuthGoogle?.renderButtons(modal, true);
  };

  window.IconIconsSiteAuthModal = {
    open(tab = 'login', next = defaultNext) {
      openModal(tab, next || defaultNext);
    },
    close() {
      closeModal();
    }
  };

  loginTabButton?.addEventListener('click', () => setTab('login'));
  registerTabButton?.addEventListener('click', () => setTab('register'));
  modal.querySelectorAll('[data-auth-modal-close]').forEach((btn) => btn.addEventListener('click', closeModal));
  modal.addEventListener('click', (event) => {
    if (event.target === modal) closeModal();
  });
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && modal.style.display === 'flex') closeModal();
  });

  document.addEventListener('click', function (event) {
    const trigger = event.target.closest('[data-open-site-auth-modal="1"]');
    if (!(trigger instanceof HTMLElement)) return;

    event.preventDefault();
    const tab = trigger.getAttribute('data-site-auth-tab') || 'login';
    const next = resolveTriggerNext(trigger) || defaultNext;
    openModal(tab, next);
  });

  loginForm?.addEventListener('submit', async function (event) {
    event.preventDefault();
    generalError?.classList.add('hidden');
    if (generalError) generalError.textContent = '';
    loginForm.querySelectorAll('[data-auth-login-error]').forEach((node) => {
      node.textContent = '';
      node.classList.add('hidden');
    });
    loginForm.querySelectorAll('input').forEach((input) => input.classList.remove('border-rose-400'));

    const formData = new FormData(loginForm);
    const next = formData.get('next') || defaultNext;
    try {
      const response = await fetch(loginUrl, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
          'Accept': 'application/json',
          'X-Requested-With': 'XMLHttpRequest',
          'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '',
        },
        body: formData,
      });
      if (response.ok) {
        window.location.assign(String(next));
        return;
      }
      const payload = await response.json().catch(() => ({}));
      if (response.status === 422 && payload.errors) {
        Object.entries(payload.errors).forEach(([field, messages]) => {
          const input = loginForm.querySelector(`[name="${field}"]`);
          const error = loginForm.querySelector(`[data-auth-login-error="${field}"]`);
          if (input) input.classList.add('border-rose-400');
          if (error) {
            error.textContent = Array.isArray(messages) ? messages[0] : String(messages);
            error.classList.remove('hidden');
          }
        });
      } else if (generalError) {
        generalError.textContent = payload.message || 'Could not sign in.';
        generalError.classList.remove('hidden');
      }
    } catch (_) {
      if (generalError) {
        generalError.textContent = 'Could not sign in.';
        generalError.classList.remove('hidden');
      }
    }
  });

  const setRegisterSubmitting = (submitting) => {
    if (!registerSubmitButton) return;
    registerSubmitButton.disabled = submitting;
    registerSubmitButton.classList.toggle('cursor-not-allowed', submitting);
    registerSubmitButton.classList.toggle('opacity-70', submitting);
  };

  const showRegisterGeneralError = (message) => {
    if (!registerGeneralError) return;
    registerGeneralError.textContent = message;
    registerGeneralError.classList.remove('hidden');
  };

  const renderRegisterErrors = (errors) => {
    let hasGeneralError = false;

    Object.entries(errors).forEach(([field, messages]) => {
      const message = Array.isArray(messages) ? messages[0] : String(messages);
      const input = registerForm?.querySelector(`[name="${field}"]`);
      const error = registerForm?.querySelector(`[data-auth-register-error="${field}"]`);

      if (input) input.classList.add('border-rose-400');
      if (error) {
        error.textContent = message;
        error.classList.remove('hidden');
        return;
      }

      if (!hasGeneralError) {
        showRegisterGeneralError(message);
        hasGeneralError = true;
      }
    });
  };

  const submitRegisterRequest = async (formData, next) => {
    setRegisterSubmitting(true);

    try {
      const response = await fetch(registerUrl, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
          'Accept': 'application/json',
          'X-Requested-With': 'XMLHttpRequest',
          'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '',
        },
        body: formData,
      });

      if (response.ok) {
        window.location.assign(String(next));
        return;
      }

      const payload = await response.json().catch(() => ({}));
      if (response.status === 422 && payload.errors) {
        renderRegisterErrors(payload.errors);
      } else {
        showRegisterGeneralError(payload.message || 'Could not create your account.');
      }
    } catch (_) {
      showRegisterGeneralError('Could not create your account.');
    } finally {
      setRegisterSubmitting(false);
    }
  };

  const ensureRegisterRecaptchaWidget = () => {
    if (!registerRecaptchaEnabled) return true;
    if (registerRecaptchaWidgetId !== null) return true;
    if (!registerRecaptchaContainer || !registerRecaptchaSiteKey || !window.grecaptcha || typeof window.grecaptcha.render !== 'function') {
      return false;
    }

    registerRecaptchaWidgetId = window.grecaptcha.render(registerRecaptchaContainer, {
      sitekey: registerRecaptchaSiteKey,
      size: 'invisible',
      callback: async (token) => {
        if (!registerPendingSubmission) {
          setRegisterSubmitting(false);
          return;
        }

        const pendingSubmission = registerPendingSubmission;
        registerPendingSubmission = null;
        pendingSubmission.formData.set('g-recaptcha-response', token);

        if (window.grecaptcha && typeof window.grecaptcha.reset === 'function') {
          window.grecaptcha.reset(registerRecaptchaWidgetId);
        }

        await submitRegisterRequest(pendingSubmission.formData, pendingSubmission.next);
      },
      'error-callback': () => {
        registerPendingSubmission = null;
        setRegisterSubmitting(false);
        showRegisterGeneralError(registerRecaptchaErrorMessage || 'Could not verify the reCAPTCHA challenge.');
      },
      'expired-callback': () => {
        registerPendingSubmission = null;
        setRegisterSubmitting(false);
        showRegisterGeneralError(registerRecaptchaErrorMessage || 'Could not verify the reCAPTCHA challenge.');
      },
    });

    return true;
  };

  registerForm?.addEventListener('submit', async function (event) {
    event.preventDefault();
    setRegisterSubmitting(false);
    registerGeneralError?.classList.add('hidden');
    if (registerGeneralError) registerGeneralError.textContent = '';
    registerForm.querySelectorAll('[data-auth-register-error]').forEach((node) => {
      node.textContent = '';
      node.classList.add('hidden');
    });
    registerForm.querySelectorAll('input').forEach((input) => input.classList.remove('border-rose-400'));

    const formData = new FormData(registerForm);
    const next = formData.get('next') || defaultNext;

    if (registerRecaptchaEnabled) {
      setRegisterSubmitting(true);

      const executeChallenge = () => {
        if (!ensureRegisterRecaptchaWidget()) {
          setRegisterSubmitting(false);
          showRegisterGeneralError(registerRecaptchaErrorMessage || 'Could not verify the reCAPTCHA challenge.');
          return;
        }

        registerPendingSubmission = { formData, next };

        if (window.grecaptcha && typeof window.grecaptcha.reset === 'function') {
          window.grecaptcha.reset(registerRecaptchaWidgetId);
        }

        window.grecaptcha.execute(registerRecaptchaWidgetId);
      };

      if (window.grecaptcha && typeof window.grecaptcha.ready === 'function') {
        window.grecaptcha.ready(executeChallenge);
      } else {
        executeChallenge();
      }

      return;
    }

    await submitRegisterRequest(formData, next);
  });
});

