div.script:
document.addEventListener('DOMContentLoaded', function () {
  const params = new URLSearchParams(window.location.search);
  if (params.get('auth_intent') !== 'cart') return;

  const lineId = params.get('auth_line');
  if (!lineId) return;

  const form = document.querySelector(`form[data-post-auth-cart-line="${lineId}"]`);
  if (!(form instanceof HTMLFormElement)) return;
  if (form.dataset.autoSubmitted === '1') return;

  params.delete('auth_intent');
  params.delete('auth_line');
  const nextUrl = window.location.pathname + (params.toString() ? `?${params.toString()}` : '') + window.location.hash;
  window.history.replaceState({}, '', nextUrl);

  form.dataset.autoSubmitted = '1';
  if (typeof form.requestSubmit === 'function') {
    form.requestSubmit();
  } else {
    form.submit();
  }
});
